from pathlib import Path
from fontTools.ttLib import TTFont
from fontTools.pens.svgPathPen import SVGPathPen
import json, html
ROOT=Path(__file__).resolve().parents[2]
B=ROOT/'brand'
INK='#111827'; PAPER='#FAF8F5'; AMBER='#F4B942'; MUTE='#655F58'
FONTS=Path('/System/Library/Fonts/Supplemental')

def textpath(text,font,size,x,y,color,spacing=0):
    f=TTFont(FONTS/font); gs=f.getGlyphSet(); cmap=f.getBestCmap(); scale=size/f['head'].unitsPerEm; cursor=0; paths=[]
    for c in text:
        name=cmap.get(ord(c),'space'); pen=SVGPathPen(gs); gs[name].draw(pen)
        paths.append(f'<path d="{pen.getCommands()}" transform="translate({x+cursor:.3f} {y}) scale({scale:.6f} {-scale:.6f})"/>')
        cursor+=gs[name].width*scale+spacing
    return f'<g fill="{color}">'+''.join(paths)+'</g>'

def mark(ink=INK,light=AMBER,micro=False):
    if micro:
        return f'<path fill="{ink}" d="M22 83 28 41H46L52 83ZM24 20 37 8 50 20ZM27 26H47V36H27Z"/><path fill="{light}" d="M55 25 88 14V35L55 37Z"/>'
    return f'<path fill="{ink}" d="M20 86 27 43H47L54 86ZM22 20 37 7 52 20ZM26 26H48V37H26Z"/><path fill="{light}" d="M56 25 90 13V35L56 37ZM55 46 79 42V57H57Z"/>'

def svg(w,h,body,label,bg=None):
    return f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}" role="img" aria-label="{html.escape(label)}"><title>{html.escape(label)}</title>'+ (f'<rect width="{w}" height="{h}" fill="{bg}"/>' if bg else '')+body+'</svg>'

def lockup(kind,ink,light):
    if kind=='symbol': return 96,96,mark(ink,light)
    if kind=='micro': return 96,96,mark(ink,light,True)
    if kind=='wordmark': return 240,110,textpath('FARO','Arial Bold.ttf',82,0,72,ink,-2)+textpath('Rayos-X','Georgia Italic.ttf',25,3,105,ink)
    if kind=='horizontal':
        return 350,116,f'<g transform="translate(0 6)">{mark(ink,light)}</g>'+textpath('FARO','Arial Bold.ttf',80,112,77,ink,-2)+textpath('Rayos-X','Georgia Italic.ttf',25,115,108,ink)
    if kind=='compact':
        return 320,96,mark(ink,light)+textpath('FARO','Arial Bold.ttf',73,106,76,ink,-2)
    return 310,245,f'<g transform="translate(102 0)">{mark(ink,light)}</g>'+textpath('FARO','Arial Bold.ttf',88,31,174,ink,-2)+textpath('Rayos-X','Georgia Italic.ttf',29,98,216,ink)

variants={'color':(INK,AMBER),'reverse':(PAPER,AMBER),'mono-dark':(INK,INK),'mono-white':('#FFFFFF','#FFFFFF')}
for k in ['horizontal','stacked','compact','wordmark','symbol','micro']:
    for v,(i,l) in variants.items():
        w,h,body=lockup(k,i,l)
        (B/'svg'/f'faro-{k}-{v}.svg').write_text(svg(w,h,body,'FARO Rayos-X · '+k+' · '+v))
for name,bg,i,l in [('dark',INK,PAPER,AMBER),('light',PAPER,INK,AMBER),('amber',AMBER,INK,INK)]:
    body=f'<g transform="translate(80 70) scale(3.65)">{mark(i,l)}</g>'
    (B/'svg'/f'faro-app-{name}.svg').write_text(svg(512,512,body,'FARO · Icono '+name,bg))
(B/'svg'/'faro-favicon.svg').write_text(svg(96,96,'<rect width="96" height="96" rx="18" fill="'+INK+'"/>'+mark(PAPER,AMBER,True),'FARO'))
# Shared visual language: a beam composed of an expanding trapezoid and a smaller echo.
pattern=f'<path fill="{AMBER}" d="M740 210 1200 45V380L740 350Z"/><path fill="{AMBER}" opacity=".35" d="M740 430 1080 380V570H770Z"/>'
body=f'<g transform="translate(65 52) scale(.70)">{lockup("horizontal",PAPER,AMBER)[2]}</g>'+pattern+textpath('Antes de firmar,','Arial Bold.ttf',69,65,318,PAPER,-1)+textpath('mira más allá.','Georgia Italic.ttf',72,65,406,PAPER,-1)+textpath('Avisos. Fotos. Contratos.','Arial.ttf',25,68,508,PAPER)+textpath('Claridad para arrendar.','Arial.ttf',22,68,551,PAPER)
(B/'social'/'faro-social-1200x630.svg').write_text(svg(1200,630,body,'FARO · Antes de firmar, mira más allá.',INK))
body=f'<path fill="{AMBER}" d="M720 250 1080 80V570L720 500Z"/>'+f'<g transform="translate(70 80) scale(.8)">{lockup("horizontal",PAPER,AMBER)[2]}</g>'+textpath('Lo que dice','Arial Bold.ttf',81,70,526,PAPER,-2)+textpath('el aviso.','Arial Bold.ttf',81,70,616,PAPER,-2)+textpath('Lo que falta','Georgia Italic.ttf',81,70,758,PAPER,-2)+textpath('por ver.','Georgia Italic.ttf',81,70,848,PAPER,-2)+textpath('Claridad para arrendar.','Arial.ttf',29,72,1003,PAPER)
(B/'social'/'faro-post-1080x1080.svg').write_text(svg(1080,1080,body,'FARO · Lo que falta por ver.',INK))
# Machine-readable design tokens, aligned with the current interface.
tokens={'color':{'ink':INK,'paper':PAPER,'beam':AMBER,'muted':MUTE,'border':'#D6D0C7','pass':'#047857','warning':'#B45309','fail':'#B91C1C'},'font':{'sans':'Arial, Helvetica, sans-serif','serif':'Georgia, serif'},'spacing':[4,8,12,16,24,32,48,64,96],'radius':{'panel':0,'button':0,'appIcon':18},'tagline':'Claridad para arrendar.'}
(B/'tokens.json').write_text(json.dumps(tokens,indent=2,ensure_ascii=False)+'\n')
(B/'tokens.css').write_text(':root {\n'+''.join(f'  --faro-{k}: {v};\n' for k,v in tokens['color'].items())+'  --faro-font-sans: Arial, Helvetica, sans-serif;\n  --faro-font-serif: Georgia, serif;\n}\n')

def img(name,style=''):
    return f'<img src="svg/{name}.svg" style="{style}" alt="{html.escape(name)}">'
def page(n,title,content,cls=''):
    return f'<section class="page {cls}"><header><span>FARO RAYOS-X / IDENTIDAD VISUAL</span><span>01.0 · OCT 2026</span></header>{content}<footer><span>{title}</span><span>{n:02d} / 08</span></footer></section>'
card=lambda content,cls='':f'<div class="card {cls}">{content}</div>'
pages=[]
pages.append(page(1,'La marca',f'<div class="cover-mark">{img("faro-horizontal-reverse","width:490px")}</div><div class="cover-title">Antes de firmar,<br><em>mira más allá.</em></div><p class="cover-sub">Claridad para arrendar.</p><div class="beam"></div>','dark cover'))
pages.append(page(2,'Concepto y voz','<div class="eyebrow">01 / IDEA CENTRAL</div><h1>Un faro para<br><em>decidir con evidencia.</em></h1><div class="cols"><div><p class="lead">FARO acompaña a quien arrienda a entender lo que un aviso, una foto o un contrato dejan fuera.</p><p>El faro representa orientación. Sus haces sugieren una F y extienden la mirada más allá de lo evidente. Rayos-X identifica la función de análisis dentro de la marca FARO.</p></div><div><h3>Clara · Rigurosa · Cercana</h3><p>Explicar sin alarmismo. Mostrar qué se observó, qué se infiere y qué falta verificar.</p><div class="quote">“No encontramos el gasto común.<br>Solicítalo antes de comparar.”</div><p class="small">Evitar promesas como “sin riesgos”, “detectamos todo” o “aprobación garantizada”.</p></div></div>'))
pages.append(page(3,'Sistema de logos','<div class="eyebrow">02 / VERSIONES</div><h1>Una marca.<br><em>Distintos espacios.</em></h1><div class="logo-grid">'+card(img('faro-horizontal-color','width:360px')+'<label>Principal · Horizontal con descriptor</label>')+card(img('faro-stacked-color','height:168px')+'<label>Vertical · Portadas y composiciones centradas</label>')+card(img('faro-compact-color','width:270px')+'<label>Compacta · FARO en espacios conocidos</label>')+card(img('faro-symbol-color','width:100px')+'<label>Símbolo · Avatar y acceso a la aplicación</label>')+'</div>'))
pages.append(page(4,'Fondos y reproducción','<div class="eyebrow">03 / COLOR Y MONOCROMÍA</div><h1>Legible en cada soporte.</h1><div class="logo-grid">'+card(img('faro-horizontal-color','width:330px')+'<label>Color sobre papel o blanco</label>')+card(img('faro-horizontal-reverse','width:330px')+'<label>Reversa sobre tinta</label>','dark')+card(img('faro-horizontal-mono-dark','width:330px')+'<label>Una tinta oscura · Impresión y documentos</label>')+card(img('faro-horizontal-mono-white','width:330px')+'<label>Una tinta blanca · Fondos oscuros</label>','dark')+'</div><p class="small">Los SVG y PNG de logos tienen fondo transparente. Sobre fotografía, usar una placa de color sólido. Nunca agregar sombras, degradados ni contornos.</p>'))
pages.append(page(5,'Paleta y tipografía','<div class="eyebrow">04 / FUNDAMENTOS</div><h1>Tinta. Papel. Luz.</h1><div class="swatches">'+''.join(f'<div><div class="swatch" style="background:{c};color:{fg}">{name}</div><b>{c}</b><p class="small">{desc}</p></div>' for name,c,fg,desc in [('Tinta',INK,PAPER,'Texto y superficies oscuras'),('Papel',PAPER,INK,'Fondo principal y aire'),('Haz',AMBER,INK,'Acento de marca y énfasis')])+'</div><div class="cols type"><div><h2 style="font-style:normal;font-family:Arial">Arial Bold / Regular</h2><p>Interfaz, titulares y datos. Alternativa: Helvetica / sans-serif del sistema. Números tabulares para importes y porcentajes.</p><div class="type-sample">Aa Bb 0123</div></div><div><h2>Georgia Italic</h2><p>Acentos editoriales y descriptor Rayos-X. Reservar para frases breves; los párrafos y controles usan sans serif.</p><div class="type-sample serif">Claridad.</div></div></div><p class="small">Estados funcionales: verificado #047857 · pendiente #B45309 · conflicto #B91C1C. Ámbar de marca no reemplaza estos estados. Añadir siempre texto o un icono.</p>'))
pages.append(page(6,'Reglas de uso','<div class="eyebrow">05 / CONSTRUCCIÓN Y ESCALA</div><h1>Espacio para ser claro.</h1><div class="cols"><div><div class="clearspace">'+img('faro-horizontal-color','width:345px')+'<span>x</span></div><h3>Área de protección</h3><p>Reservar x a cada lado del logo, donde x equivale a un cuarto de la altura del símbolo. Ningún texto o borde debe entrar en esa zona.</p></div><div><h3>Tamaños mínimos de trabajo</h3><p>Horizontal con descriptor: 200 px / 45 mm.<br>Vertical: 150 px / 35 mm.<br>Compacta: 120 px / 28 mm.<br>Símbolo completo: 32 px / 8 mm.<br>Micro sin segundo haz: 16–24 px.</p><h3>Conservar la forma</h3><p>No estirar, rotar, recolorear por estado ni alterar la relación símbolo / nombre. No usar ámbar como texto pequeño sobre papel.</p><p class="small">Los mínimos impresos son orientativos: confirmar con una prueba en el soporte y sistema de impresión final.</p></div></div><div class="micro-line">'+''.join(img('faro-app-'+x,'width:72px;height:72px;border-radius:16px') for x in ['dark','light','amber'])+'<p>Iconos en 512 y 1024 px. Favicon simplificado de 16 y 32 px.<br>El sistema operativo puede aplicar su propia máscara al icono cuadrado.</p></div>'))
pages.append(page(7,'Aplicaciones','<div class="eyebrow">06 / LA MARCA EN USO</div><h1>Del producto a la conversación.</h1><div class="applications"><img src="social/faro-social-1200x630.svg" alt="Portada social"><div class="mock"><div class="mockhead">'+img('faro-horizontal-color','width:185px')+'</div><div class="eyebrow">REVISIÓN DE ARRIENDO</div><h2>Todo a la vista.</h2><p>Reúne el aviso, las fotos<br>y el contrato para comparar.</p><div class="status"><b>✓ Verificado</b><span>Información respaldada</span></div><div class="status warning"><b>! Por confirmar</b><span>Falta evidencia</span></div><button>Revisar un aviso →</button><p class="small">Ejemplo visual de aplicación.</p></div></div>'))
pages.append(page(8,'Entrega y formatos','<div class="eyebrow">07 / ARCHIVOS Y IMPLEMENTACIÓN</div><h1>Lista para usar.<br><em>Lista para crecer.</em></h1><div class="cols"><div><h3>SVG / Originales vectoriales</h3><p>24 versiones: horizontal, vertical, compacta, nombre, símbolo y micro, en color, reversa y dos monocromías. Letras convertidas a trazados; no requieren fuentes instaladas.</p><h3>PNG / Exportación transparente</h3><p>Las mismas variantes en resolución 3×. Iconos en 512 y 1024 px; favicon en 16 y 32 px; avatar en 400 px.</p><h3>Redes / Piezas iniciales</h3><p>Portada de 1200 × 630 px y publicación de 1080 × 1080 px, en SVG y PNG.</p></div><div><h3>Producto / Integración</h3><p>Marca horizontal, favicon e icono de aplicación incorporados al cliente. Tokens JSON y CSS para extender el sistema.</p><h3>Fuente / Mantenimiento</h3><p>El generador Python conserva geometría y exporta letras a trazados con FontTools. Arial y Georgia se utilizan desde el sistema; sus archivos de fuente no se redistribuyen.</p><div class="quote">Nombre público: FARO Rayos-X<br>Marca corta: FARO<br>Firma: Claridad para arrendar.</div><p class="small">Versión inicial de identidad. No incluye registro de marca ni comprobación de disponibilidad legal.</p></div></div>'))
css='''*{box-sizing:border-box}body{margin:0;background:#D6D0C7;color:#111827;font-family:Arial,Helvetica,sans-serif}.page{width:1120px;height:792px;position:relative;padding:68px 64px 58px;background:#FAF8F5;margin:24px auto;overflow:hidden;break-after:page}header,footer{position:absolute;left:64px;right:64px;display:flex;justify-content:space-between;font-size:10px;letter-spacing:1.8px;font-weight:bold}header{top:26px;border-bottom:1px solid #D6D0C7;padding-bottom:12px}footer{bottom:24px;letter-spacing:.8px}.dark{background:#111827;color:#FAF8F5}.dark header{border-color:#414753}.eyebrow{font-size:11px;font-weight:bold;letter-spacing:2px;margin:10px 0 20px;color:#655F58}h1{font-size:50px;line-height:1.06;letter-spacing:-2px;margin:0 0 28px}em,.serif,h2{font-family:Georgia,serif;font-weight:normal;font-style:italic}h2{font-size:30px;margin:0 0 14px}h3{font-size:17px;margin:0 0 12px}p{font-size:17px;line-height:1.6;margin:0 0 23px}.lead{font-size:23px;line-height:1.45}.small{font-size:13px;line-height:1.6}.cols{display:grid;grid-template-columns:1fr 1fr;gap:52px}.quote{border-left:4px solid #F4B942;padding:16px 20px;background:#F0ECE5;font-size:18px;line-height:1.6;margin:20px 0}.cover-mark{position:relative;z-index:1;margin-top:54px}.cover-title{position:relative;z-index:1;font-size:72px;letter-spacing:-2.8px;line-height:1.08;margin-top:85px}.cover-sub{margin-top:28px;font-size:22px}.beam{position:absolute;right:-40px;top:145px;width:365px;height:405px;background:#F4B942;clip-path:polygon(0 26%,100% 0,100% 100%,0 73%)}.logo-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.card{height:205px;border:1px solid #D6D0C7;display:flex;align-items:center;justify-content:center;position:relative;padding:10px 24px 42px}.card label{position:absolute;bottom:17px;left:24px;font-size:12px}.swatches{display:grid;grid-template-columns:1fr 1fr 1fr;gap:18px}.swatch{height:100px;display:flex;align-items:end;padding:18px;font-size:23px;border:1px solid #D6D0C7;margin-bottom:12px}.swatches b{font-size:14px}.swatches p{margin-top:8px}.type{margin-top:14px}.type-sample{font-size:54px;letter-spacing:-2px}.type p{font-size:15px}.clearspace{border:1px dashed #B45309;padding:40px 20px;margin-bottom:23px;position:relative}.clearspace span{position:absolute;top:9px;left:10px;font-size:14px;color:#B45309}.micro-line{display:flex;align-items:center;gap:18px;border-top:1px solid #D6D0C7;margin-top:12px;padding-top:20px}.micro-line p{font-size:14px;margin:0 0 0 14px}.applications{display:grid;grid-template-columns:1.35fr 1fr;gap:24px}.applications>img{width:100%;margin-top:44px}.mock{border:1px solid #D6D0C7;padding:26px;background:white}.mockhead{border-bottom:1px solid #D6D0C7;padding-bottom:18px;margin-bottom:24px}.mock p{font-size:14px}.status{padding:12px;border:1px solid #047857;margin-bottom:10px;color:#047857;font-size:13px;display:flex;justify-content:space-between;gap:10px}.warning{color:#B45309;border-color:#B45309}button{border:0;background:#111827;color:white;padding:15px 20px;width:100%;font-weight:bold;margin:12px 0}.mock .small{margin:0;color:#655F58;font-size:11px}@media print{@page{size:1120px 792px;margin:0}body{background:none}.page{margin:0;print-color-adjust:exact;-webkit-print-color-adjust:exact}}'''
(B/'guia-visual.html').write_text('<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>FARO Rayos-X · Guía de identidad</title><style>'+css+'</style><body>'+''.join(pages)+'</body></html>')
