board=f'''<!doctype html><html lang="es"><meta charset="utf-8"><title>FARO · Identidad visual</title><style>*{{box-sizing:border-box}}body{{margin:0;background:{PAPER};color:{INK};font-family:Arial,sans-serif}}.board{{width:1440px;padding:55px}}.top{{display:flex;justify-content:space-between;font-size:12px;letter-spacing:2px;font-weight:bold;margin-bottom:30px}}.hero{{background:{INK};height:500px;padding:64px;position:relative;overflow:hidden;color:{PAPER}}}.hero img{{width:410px}}h1{{font-size:66px;line-height:1.07;letter-spacing:-2px;margin:60px 0 20px}}em{{font-family:Georgia;font-weight:normal}}.beam{{position:absolute;right:0;top:55px;width:360px;height:380px;background:{AMBER};clip-path:polygon(0 28%,100% 0,100% 100%,0 72%)}}.hero p{{font-size:20px}}.row{{display:grid;grid-template-columns:1fr 1fr 1fr;gap:20px;margin-top:20px}}.tile{{height:255px;border:1px solid #D6D0C7;display:flex;align-items:center;justify-content:center;position:relative}}.tile img{{max-width:280px;max-height:170px}}label{{position:absolute;bottom:18px;left:22px;font-size:11px;letter-spacing:1px}}.tile.dark{{background:{INK}}}.tile.icons{{gap:20px}}.tile.icons img{{width:96px;border-radius:24px}}.palette{{display:flex;height:105px;margin-top:20px}}.palette div{{flex:1;padding:22px;font-size:20px;display:flex;justify-content:space-between;align-items:center}}.bottom{{display:flex;justify-content:space-between;margin-top:24px;font-size:13px}}.type{{font-size:23px}}.border{{border:1px solid #D6D0C7}}</style><div class="board"><div class="top"><span>FARO RAYOS-X / SISTEMA DE IDENTIDAD</span><span>01.0 · 2026</span></div><div class="hero">{img('faro-horizontal-reverse')}<div class="beam"></div><h1>Antes de firmar,<br><em>mira más allá.</em></h1><p>Claridad para arrendar.</p></div><div class="row"><div class="tile">{img('faro-stacked-color')}<label>01 / FIRMA VERTICAL</label></div><div class="tile dark">{img('faro-horizontal-mono-white')}<label style="color:white">02 / MONOCROMÍA</label></div><div class="tile icons">{img('faro-app-dark')}{img('faro-app-amber')}<label>03 / ICONOS DE APLICACIÓN</label></div></div><div class="palette"><div style="background:{INK};color:{PAPER}">Tinta <small>{INK}</small></div><div class="border">Papel <small>{PAPER}</small></div><div style="background:{AMBER}">Haz <small>{AMBER}</small></div></div><div class="bottom"><span class="type"><b>FARO</b> / <em>Rayos-X</em></span><span>Orientación · Evidencia · Claridad</span></div></div></html>'''
(B/'vista-general.html').write_text(board)
